def solve(tables):
    orders = tables["orders"]
    dates = pd.to_datetime(orders["placed_on"], errors="coerce").dropna()
    if dates.empty:
        return pd.DataFrame({"first_order": [None], "last_order": [None]})
    return pd.DataFrame({
        "first_order": [dates.min().strftime("%Y-%m-%d")],
        "last_order": [dates.max().strftime("%Y-%m-%d")],
    })
```

